`normalizeAssignment` converts nullable, incomplete assignment data into a complete view. For `null`, missing, or whitespace-only text fields, use `Unknown organization`, `Unknown role`, and `Start unavailable`. Preserve nonblank organization, role, and start strings exactly. A missing or blank logo becomes `null`; otherwise preserve it exactly. For notes, discard `null`, `undefined`, and whitespace-only entries, trim each retained entry, and preserve order and duplicates. Always allocate a fresh notes array and do not mutate the input.

Known-bad source:
```ts
export interface AssignmentInput {
  organization?: string;
  role?: string;
  start?: string;
  logo?: string;
  notes?: readonly (string | null | undefined)[];
}

export interface AssignmentView {
  organization: string;
  role: string;
  start: string;
  logo: string | null;
  notes: string[];
}

function textOr(value: string | undefined, fallback: string): string {
  return value === undefined || value.trim() === "" ? fallback : value;
}

export function normalizeAssignment(input: AssignmentInput | null): AssignmentView {
  const value = input ?? {};
  return {
    organization: textOr(value.organization, "Unknown organization"),
    role: textOr(value.role, "Unknown role"),
    start: textOr(value.start, "Start unavailable"),
    logo: value.logo === undefined || value.logo.trim() === "" ? null : value.logo,
    notes: (value.notes ?? [])
      .filter((note): note is string => note !== null && note !== undefined)
      .map((note) => note.trim()),
  };
}
```

