import { normalizeAssignment } from './solution';
import type { AssignmentInput } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

equal(normalizeAssignment(null), {
  organization: 'Unknown organization',
  role: 'Unknown role',
  start: 'Start unavailable',
  logo: null,
  notes: [],
}, 'null input defaults');

equal(normalizeAssignment({}), {
  organization: 'Unknown organization',
  role: 'Unknown role',
  start: 'Start unavailable',
  logo: null,
  notes: [],
}, 'missing fields default');

equal(normalizeAssignment({
  organization: ' \t ',
  role: '\n',
  start: '   ',
  logo: '\t',
  notes: [null, undefined, '', '   ', '\n', ' first ', 'second', ' first '],
}), {
  organization: 'Unknown organization',
  role: 'Unknown role',
  start: 'Start unavailable',
  logo: null,
  notes: ['first', 'second', 'first'],
}, 'blank fields and note filtering');

const notes: Array<string | null | undefined> = ['  note one  ', null, 'note two', '  note one  '];
const input: AssignmentInput = {
  organization: '  Org  ',
  role: ' Role ',
  start: ' 2026-01-01 ',
  logo: ' logo.svg ',
  notes,
};
const snapshot = notes.slice();
const view = normalizeAssignment(input);
equal(view, {
  organization: '  Org  ',
  role: ' Role ',
  start: ' 2026-01-01 ',
  logo: ' logo.svg ',
  notes: ['note one', 'note two', 'note one'],
}, 'nonblank text is preserved and notes are trimmed');
equal(notes, snapshot, 'input notes are not mutated');
assert(view.notes !== notes, 'notes result is fresh');
notes[0] = 'changed';
assert(view.notes[0] === 'note one', 'result does not retain input notes array');

const firstEmpty = normalizeAssignment({ notes: [] });
const secondEmpty = normalizeAssignment({ notes: [] });
assert(firstEmpty.notes !== secondEmpty.notes, 'empty notes arrays are freshly allocated');

